<script setup lang="ts">import {computed,ref} from "vue";import {useRouter} from "vue-router";import {Plus} from "lucide-vue-next";import AppShell from "@/components/zs/AppShell.vue";import PageHeader from "@/components/zs/PageHeader.vue";import Panel from "@/components/zs/Panel.vue";import DataTable,{type Column} from "@/components/zs/DataTable.vue";import Toolbar from "@/components/zs/Toolbar.vue";import SearchInput from "@/components/zs/SearchInput.vue";import StatusBadge from "@/components/zs/StatusBadge.vue";import StatCard from "@/components/zs/StatCard.vue";import ZButton from "@/components/zs/ZButton.vue";import {useAsyncData} from "@/composables/useAsyncData";import {crmRepository} from "@/services/crm/repository";import {useCompanyStore} from "@/stores/company";import {formatMoney} from "@/lib/money";import {setPageMeta} from "@/lib/page-meta";import type {CrmDeal} from "@/types/crm";setPageMeta('Deals','Qualified opportunities, ownership, value and expected close dates.');const c=useCompanyStore(),s=useAsyncData(()=>crmRepository.deals(c.activeCompanyId),{watch:[()=>c.activeCompanyId]}),q=ref(''),stage=ref('All stages'),router=useRouter(),rows=computed(()=>(s.data.value??[]).filter(x=>(stage.value==='All stages'||x.stage===stage.value)&&`${x.name} ${x.company}`.toLowerCase().includes(q.value.toLowerCase()))),pipeline=computed(()=>rows.value.filter(x=>!['Won','Lost'].includes(x.stage)).reduce((a,x)=>a+x.value,0));const columns:Column[]=[{key:'name',header:'Deal'},{key:'company',header:'Company'},{key:'stage',header:'Stage'},{key:'value',header:'Value',align:'right',class:'num'},{key:'probability',header:'Probability',align:'right'},{key:'close',header:'Expected close'},{key:'owner',header:'Owner'}];</script><template><AppShell><PageHeader title="Deals" description="Manage qualified opportunities separately from lead qualification"><template #actions><ZButton><Plus class="size-4"/>New deal</ZButton></template></PageHeader><div class="mb-4 grid gap-3 sm:grid-cols-3"><StatCard label="Open pipeline" :value="formatMoney(pipeline)" tone="brand"/><StatCard label="Open deals" :value="String(rows.filter(x=>!['Won','Lost'].includes(x.stage)).length)"/><StatCard label="Weighted pipeline" :value="formatMoney(rows.reduce((a,x)=>a+Math.round(x.value*x.probability/100),0))" tone="success"/></div><Panel><Toolbar><SearchInput v-model="q" placeholder="Search deals"/><select v-model="stage" class="field w-40"><option>All stages</option><option>Qualified</option><option>Proposal</option><option>Negotiation</option><option>Won</option><option>Lost</option></select></Toolbar><DataTable :columns="columns" :rows="rows" :min-width="1000"><template #name="{row}:{row:CrmDeal}"><button class="font-medium text-content-brand hover:underline" @click="router.push(`/crm/deals/${row.id}`)">{{row.name}}</button></template><template #company="{row}">{{row.company}}</template><template #stage="{row}"><StatusBadge :status="row.stage"/></template><template #value="{row}">{{formatMoney(row.value)}}</template><template #probability="{row}">{{row.probability}}%</template><template #close="{row}">{{row.expectedClose}}</template><template #owner="{row}">{{row.owner}}</template></DataTable></Panel></AppShell></template>